#include <vector>
using namespace std;

class Solution {
public:
    bool canChoose(vector<vector<int>>& groups, vector<int>& nums) {
        int idx = 0;
        int n = nums.size();
        for (const auto& g : groups) {
            int m = g.size();
            bool found = false;
            while (idx + m <= n) {
                bool match = true;
                for (int k = 0; k < m; ++k) {
                    if (nums[idx + k] != g[k]) { match = false; break; }
                }
                if (match) {
                    idx += m;
                    found = true;
                    break;
                }
                idx++;
            }
            if (!found) return false;
        }
        return true;
    }
};

